use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        // Shape: number of rows equals |y|
        result.0.len() == y.len(),
        result.1.len() == y.len(),

        // Each row has |x| columns
        forall|i: int|
            0 <= i < y.len() ==>
                result.0[i].len() == x.len()
                && result.1[i].len() == x.len(),

        // Values: X grid copies x across each row
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==>
                result.0[i][j] == x[j],

        // Values: Y grid copies y down each column (constant per row)
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==>
                result.1[i][j] == y[i],
{
    let mut X: Vec<Vec<f32>> = Vec::new();
    let mut Y: Vec<Vec<f32>> = Vec::new();

    let mut i: usize = 0;
    while i < y.len()
        invariant
            0 <= i <= y.len(),
            X.len() == i,
            Y.len() == i,
            forall|r: int| 0 <= r < i ==> X[r].len() == x.len() && Y[r].len() == x.len(),
            forall|r: int, c: int|
                0 <= r < i && 0 <= c < x.len() ==> X[r][c] == x[c],
            forall|r: int, c: int|
                0 <= r < i && 0 <= c < x.len() ==> Y[r][c] == y[r],
    {
        let mut row_x: Vec<f32> = Vec::new();
        let mut row_y: Vec<f32> = Vec::new();

        let mut j: usize = 0;
        while j < x.len()
            invariant
                0 <= j <= x.len(),
                row_x.len() == j,
                row_y.len() == j,
                forall|c: int| 0 <= c < j ==> row_x[c] == x[c],
                forall|c: int| 0 <= c < j ==> row_y[c] == y[i as int],
        {
            row_x.push(x[j]);
            row_y.push(y[i]);
            j += 1;
        }

        X.push(row_x);
        Y.push(row_y);
        i += 1;
    }

    (X, Y)
}

} // verus!